arguments.command:
cd /home/user && ls && python3 -c "
from pptx import Presentation
from pptx.util import Emu
p=Presentation('189_4.pptx')
for i,s in enumerate(p.slides,1):
    print('=== slide',i, s.slide_layout.name)
    for sh in s.shapes:
        print(' shape', sh.shape_type, sh.name, sh.has_text_frame, sh.left,sh.top,sh.width,sh.height)
        if sh.has_text_frame:
            for para in sh.text_frame.paragraphs:
                print('   para align',para.alignment, repr(para.text))
                for r in para.runs:
                    f=r.font
                    print('    run',repr(r.text),'name',f.name,'size',f.size,'bold',f.bold,'italic',f.italic,'color',f.color.type, getattr(f.color,'rgb',None) if f.color.type is not None else None)
"

